    @Override
    public void setupAnim(StormRenderState s) {
        super.setupAnim(s);
        StormSpine.Pose p = s.pose;
        for (int k = 0; k < StormSpine.N; k++) {
            ModelPart bone = spine[k];
            int j = StormSpine.boneJoint(k);
            bone.x = p.modelX(j);
            bone.y = p.modelY(j);
            bone.z = p.modelZ(j);
            bone.xRot = p.pitch[k] * Mth.DEG_TO_RAD;
            bone.yRot = p.yaw[k] * Mth.DEG_TO_RAD;
            bone.zRot = 0;
        }
        head.x = p.modelX(0);
        head.y = p.modelY(0);
        head.z = p.modelZ(0);
        head.xRot = p.headPitch * Mth.DEG_TO_RAD;
        head.yRot = p.headYaw * Mth.DEG_TO_RAD;
        head.zRot = 0;
        jaw.xRot = s.jaw * 0.6F;
        // the arms, and the back legs in the same pose
        for (int side = 0; side < 2; side++) {
            for (int part = 0; part < 4; part++) {
                pose(arms[side][part], p.armX(part, side), p.armY(part, side), p.armZ(part, side));
                pose(legs[side][part], p.armX(part, side), p.armY(part, side), p.armZ(part, side));
            }
            for (int f = 0; f < 3; f++) {
                for (int i = 0; i < 2; i++) {
                    if (fingers[side][f][i] != null) fingers[side][f][i].zRot = p.fingers(side);
                    if (toes[side][f][i] != null) toes[side][f][i].zRot = p.fingers(side);
                }
            }
        }
        // the stars turn around the body, slowly
        float seconds = s.ageInTicks / 20F;
        for (int i = 0; i < stars.length; i++) stars[i].zRot += (starTurns[i] * seconds % 360) * Mth.DEG_TO_RAD;

        // the star platform: under the coiled body, when it rests in the air
        float rest = s.coil * s.air;
        platform.visible = rest > 0.05F;
        if (platform.visible) {
            float low = Float.MAX_VALUE, cx = 0, cz = 0;
            int n = 0;
            for (int k = StormSpine.TORSO; k <= StormSpine.N; k++) {
                low = Math.min(low, p.jy[k]);
                cx += p.modelX(k);
                cz += p.modelZ(k);
                n++;
            }
            // (the platform turns around its centre; the parts of the root are placed in the space of the model)
            platform.x = cx / n;
            platform.z = cz / n;
            platform.y = 24.0F - (low - 12);
            platform.xScale = platform.yScale = platform.zScale = Mth.clamp((rest - 0.05F) / 0.5F, 0, 1);
            platform.yRot = s.ageInTicks * 0.01F;
        }
    }

    private static void pose(ModelPart part, float x, float y, float z) {
        if (part == null) return;
        part.xRot = x;
        part.yRot = y;
        part.zRot = z;
    }
